    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    Collections.sort(result, new Comparator<Integer>() {
        @Override
        public int compare(Integer o1, Integer o2) {
            return o1.toString().compareTo(o2.toString());
        }
    });
    return result;
}

